    (variant.terrain.floatingRocks || []).forEach((cells, i) => this.board.addTerrain(cells, { id: 'frock' + i, type: 'Floating Rocks', obstacle: true, obscuring: true, destructible: false, indestructible: true, elevated: true, blocksPrim: true, climb: 4 }));
