      def = all.length === 1 ? all[0] : await this.ask({ type: 'choice', titan: t, title: '⚡ 각성 — Godform 선택 (Exalted = Grand Theft: 죽음을 피할 수 없음, Fused Souls, Trespass 1)', options: all.map(g => ({ label: `${g.exalted ? '🌟 [Grand Theft] ' : ''}${g.name}: ${Object.keys(g.abilities).join(' / ')}`, value: g })) });
