    this.say(`🔱 ${t.name}: ${def.name} Godform으로 각성!${theft ? ' (Grand Theft — Fused Souls: 이 타이탄이 죽으면 Argonaut도 죽고, 죽음을 피할 수 없음)' : ''} (Trespass ${t.godform.trespass})`, 'good');
