  async straightMove(t, max, label) { const dir = await this.ask({ type: 'choice', titan: t, title: `${label}: 직선 이동 방향`, options: [{ label: '안 함', value: null }, ...DIR_LIST.map(d => ({ label: d, value: d }))] }); if (!dir) return; const bp = t.gear.some(q => !q.discarded && /Primordial Bypass/.test(this.gearText(q, t))); let cur = { ...t.pos }, last = null, pn = 0; const steps = []; for (let i = 0; i < max; i++) { const n = { c: cur.c + DIRS[dir][0], r: cur.r + DIRS[dir][1] }; if (!this.board.inBounds(n.c, n.r) || this.board.hasWall(cur, n) || this.board.isObstacle(n.c, n.r)) break; const inP = this.primContains(n); if (inP && !bp) break; cur = n; if (inP) pn++; else if (!this.titanAt(n.c, n.r) && !this.board.isChasm(n.c, n.r)) { last = { ...n, pn }; steps.push(last); } } if (!steps.length) { this.say(`${label}: 이동할 수 없음`); return; } const pick = await this.ask({ type: 'choice', titan: t, title: `${label}: 멈출 칸`, options: steps.map(p => ({ label: `${cellLabel(p)}${p.pn ? ` (Primordial ${p.pn}칸 통과)` : ''}`, value: p })) }); t.pos = { c: pick.c, r: pick.r }; if (pick.pn) { t.pain = (t.pain || 0) + pick.pn; this.kratosPool.break = (this.kratosPool.break || 0) + pick.pn; this.say(`${t.name}: Primordial Bypass — Pain +${pick.pn}, Break +${pick.pn}`); } this.say(`${t.name}: ${label} → ${cellLabel(pick)}`); await this.landOn(t); }
  placeCarpet(cells) { if (this._carpet) for (const [k, v] of this._carpet.under) { if (v) this.board.terrain.set(k, v); else this.board.terrain.delete(k); } const under = new Map(); for (const p of cells) { const k = key(p.c, p.r); under.set(k, this.board.terrain.get(k) || null); this.board.terrain.set(k, { id: 'carpet', type: 'Carpet of the Anemoi', obstacle: false, obscuring: false, destructible: false, indestructible: true, elevated: true, cell: { ...p } }); } this._carpet = { cells: cells.map(p => ({ ...p })), under }; this.notify(); }
