  // ---------------- Triskelion ----------------
  async gainRage(t, n, involuntary = true) { if (n > 1 && t && t.alive) { const zg = t.gear.find(g => !g.exhausted && !g.discarded && /⟳ When you are about to gain RAGE, lower this gain to 1/.test(this.gearText(g, t))); if (zg && await this.ask({ type: 'yn', titan: t, title: `${zg.card.name}: Rage +${n} → +1로 줄이기? (소진)`, options: [{ label: '줄인다', value: true }, { label: '그대로', value: false }] })) { zg.exhausted = true; n = 1; this.say(`${t.name}: ${zg.card.name} — Rage 획득 1로`); } } if (n > 0 && t && t.conditions && t.conditions.includes('Sealed')) { this.say(`${t.name}: Sealed — Rage를 얻을 수 없음`); return; } if (involuntary && n > 0 && this.fr(t) > 0) { const g = t.gear.find(g => !g.exhausted && !g.discarded && /Ψ⟳ When you are about to gain Rage from an effect other than your Attack, ignore this gain/.test(this.gearText(g, t))); if (g) { const ok = await this.ask({ type: 'yn', titan: t, title: `${g.card.name}: Rage +${n} 무시? (Fate+1, 소진)`, options: [{ label: '무시', value: true }, { label: '받는다', value: false }] }); if (ok) { g.exhausted = true; await this.gainFate(t, 1); return; } } } if (involuntary && n > 0 && await this.argoHook('Forced Kratos Cooldown', `${t.name}의 비자발적 Rage +${n} 무시?`, t)) return; t.rage += n; if (t.rage > 9 && this.gf(t, 'Ares')) { t.rage = 9; this.say(`${t.name}: God of War — 9를 넘는 Rage 무시`); } if (t.rage > 9 && t.danger >= 9 && t.gear.some(g => !g.discarded && /If you gain Rage above 9, instead of dying, draw an Obol/.test(this.gearText(g, t)))) { t.rage = 9; this.say(`${t.name}: Blades of Rage — Rage 9 초과, 죽는 대신 Obol`, 'bad'); await this.obolDraw(t, 10); } if (t.rage > 9) { t.rage = 9; t.rageDoom = true; this.say(`${t.name}: Rage가 9를 넘었습니다 — 현재 액션 후 분노에 삼켜져 사망합니다!`, 'bad'); } this.checkPT(t); const h = this.ptHolder(); if (h && h !== t && !h.ptLocked && h.rage === t.rage && this.mn(t, 'Blood on Your Hands', 1)) { const ok = await this.ask({ type: 'yn', titan: t, title: `Blood on Your Hands: Rage가 PT(${h.name})와 같음 — PT 토큰 가져오기?`, options: [{ label: '가져온다', value: true }, { label: '패스', value: false }] }); if (ok) { h.pt = false; t.pt = true; this.say(`${t.name}: Priority Target 획득`); } } }
  async gainFate(t, n, o = {}) { if (n > 0 && !o.nc && t && t.alive && t.danger < 9) { const he = this.gearHas(t, /When you are about to gain any Fate as an ability cost, you may gain \+1 Danger instead of \+1 Fate/); if (he) { const lim = /Twice per Round instead/.test(this.gearText(he, t)) ? 2 : 1; if (he._r !== this.round) { he._r = this.round; he._n = 0; } if (he._n < lim) { const ok = await this.ask({ type: 'yn', titan: t, title: `${he.card.name}: 비용 Fate +1 대신 Danger +1? (라운드 ${he._n}/${lim})`, options: [{ label: 'Danger +1', value: true }, { label: 'Fate 그대로', value: false }] }); if (ok) { he._n++; n -= 1; this.say(`${he.card.name}: Fate 대신 Danger +1`); await this.gainDanger(t, 1, { source: he.card.name }); if (!t.alive || n <= 0) return; } } } } t.fate += n; if (t.fate > 9) { t.fate = 9; await this.drawMoiros(t); } }
