    { const ct = ((this.data.decks.conditions || {})[name] || {}).type; if (t && /^(Mind|Body)$/.test(ct || '') && t.gear.some(g => !g.discarded && /Ignore Mind and Body Condition cards/.test(this.gearText(g, t)))) { this.say(`${t.name}: ${name} (${ct}) 무시`, 'good'); return; } }
