  async bleedLimit(t) { if (!t.conditions.includes('Bleeding')) return; if ((t.bleeding || 0) <= 0) { t.conditions = t.conditions.filter(c => c !== 'Bleeding'); t.bleeding = 0; this.say(`${t.name}: Bleeding 토큰 0 — Bleeding 카드 버림`, 'good'); return; } let L = t.def.bleedingLimit || 4; for (const g of t.gear) { if (g.discarded) continue; const v = /Bleeding Limit (\d)\./.exec(this.gearText(g, t)); if (v) L = Math.max(L, +v[1]); } L -= (this.trait('Bleed Your Heart Out') ? 1 : 0); if (t.bleeding > L) { if (await this.godlyComfort(t, 'Bleeding')) { t.bleeding = L - 1; return; } this.say(`${t.name}: Bleeding 토큰 ${t.bleeding} > Limit ${L} — 사망`, 'bad'); await this.kill(t); } }
