  precisionMods(t) { let p = this.anchorPrec(t) + (this.asc(t) >= 1 ? 1 : 0) + (this.inBlindspot(t) ? 1 : 0) + (t.castoffBuff ? 1 : 0) - (this.hasFated(t, 'Coward') && !t.onVP && this.inFront(t.pos) ? 1 : 0) + t.tokens.precision + (t.godform ? t.godform.def.precision || 0 : 0); { const d = this.despairEff(t); if (d === 1) p -= 1; else if (d >= 2) p -= 3; } if (this.liveTitans().some(x => x !== t && this.mn(x, 'A Dream You Hold', 1) && Board.dist(x.pos, t.pos) === 1)) p += 1; if (this.inRear(t.pos) && this.mn(t, 'A Broken Promise', 1)) p += 1; if (t.pt && this.mn(t, 'Blood on Your Hands', 2)) p += 1; if (!t.ignoreMind && t.conditions.includes('Fear')) p -= 2; if (!t.ignoreMind && t.conditions.includes('Dread')) p -= (this.inRear(t.pos) ? 2 : 4); if (t.hidden) p += 1; for (const g of t.gear) { if (g.discarded || g.blank || /^hand/.test(g.card.slot)) continue; const tx = this.gearText(g, t); if (/(^|\. )\+1 Precision\./.test(tx)) p += 1; if (/(^|\. )\+2 Precision\./.test(tx)) p += 2; if (/\+1 Precision for each adjacent Titan/.test(tx)) p += this.liveTitans().filter(x => x !== t && Board.dist(x.pos, t.pos) === 1).length; } return p; }

