      if (this.prim.traits['Friendly Warning']) { x -= 2; this.say(`Friendly Warning: Knockback −2 → ${Math.max(0, x)}`); } if (this.prim.traits['Fleet of Hands']) { x += 2; this.say(`Fleet of Hands: Knockback +2 → ${x}`); }
      x = await this.reduceSuffered(t, 'Knockbacks', x);
      if (x > 0 && this.ab(t, 'Stubborn')) { const ok = await this.ask({ type: 'yn', titan: t, title: `Stubborn: Knockback ${x} → ${x - 1}?${this._kbPrev(x, x - 1)}`, options: [{ label: '줄인다', value: true }, { label: '그대로', value: false }] }); if (ok) x--; }
      if (x > 0 && this.mn(t, 'Imprisonment', 1)) { const ok = await this.ask({ type: 'yn', titan: t, title: `Imprisonment: Knockback ${x} → ${Math.max(0, x - 2)}로 줄일까요?${this._kbPrev(x, Math.max(0, x - 2))}`, options: [{ label: '줄인다', value: true }, { label: '그대로', value: false }] }); if (ok) x = Math.max(0, x - 2); }
