    if (this.prim.def.dahakaD) { await this.dhTurnStart(t); if (!t.alive) return; }
    if (this.prim.def.babelD) { await this.babelTurnStart(t); if (!t.alive) return; }
    if (((this.prim.def.cycle || 0) >= 4)) { await this.midasTurnStart(t); if (!t.alive) return; }
    if (t.gear.some(g => !g.discarded && /Start of your turn: Gain 1 Midas token/.test(g.card.text || ''))) { await this.gainMidas(t, 1); if (!t.alive) return; }
    for (const g of t.gear) if (!g.discarded && g.cool && t.rage > 0) { const v = await this.ask({ type: 'choice', titan: t, title: `${g.card.name}: Cool 토큰 X개 버리고 Rage −X? (Cool ${g.cool}, Rage ${t.rage})`, options: Array.from({ length: Math.min(g.cool, t.rage) + 1 }, (_, i) => ({ label: i ? `−${i}` : '안 함', value: i })) }); if (v) { g.cool -= v; t.rage -= v; this.say(`${t.name}: Rage −${v} → ${t.rage}`); this.checkPT(t); } }
    if (t.gear.some(g => !g.discarded && /Start of your turn: Gain 1 Ambrosia token or 2 Bleeding tokens/.test(g.card.text || ''))) { const v = await this.ask({ type: 'choice', titan: t, title: 'Poseidonis: 턴 시작', options: [{ label: 'Ambrosia +1', value: 'a' }, { label: 'Bleeding 토큰 +2', value: 'b' }] }); if (v === 'a') await this.gainAmbrosia(t, 1); else await this.addCondition(t, 'Bleeding', { tokens: 2 }); if (!t.alive) return; }
    if (t.gear.some(g => !g.discarded && /The Mark: If you start your turn adjacent to another Titan, they die/.test(g.card.text || ''))) { for (const o of this.liveTitans().filter(x => x !== t && !x.offBoard && !t.offBoard && Board.dist(x.pos, t.pos) === 1)) { this.say(`${t.name}: The Mark — 인접한 ${o.name} 사망`, 'bad'); await this.safe(() => this.kill(o)); } }
    { const pg = t.gear.find(g => !g.discarded && /Aeon Transgress: At the start of your turn, make an Awakening Roll/.test(g.card.text || '')); if (pg && this.awk && (!t.godform || (t.danger >= 6 && !t.godform.beyond))) { const r = this.rng.d10(); const v = r + t.rage; this.say(`${t.name}: Aeon Transgress — 각성 굴림 d10=${r} + Rage ${t.rage} = ${v} (10+)`, v >= 10 ? 'good' : ''); if (v >= 10) { if (t.godform) { t.godform.beyond = true; t.godform.trespass = t.godform.def.trespass; this.say(`${t.name}: Went Beyond — Trespass 회복, Precision +1, Godform Power die 1단계 상승`, 'good'); } else { t._aeonDie = true; await this.awaken(t, { fromObol: true, inline: true }); } } } }
    for (const g of t.gear) if (g.discarded && !g.lost && /It re-appears in its wielder's hand at the start of their turn/.test(g.card.text || '')) { g.discarded = false; g.exhausted = false; this.say(`${t.name}: ${g.card.name} 다시 손으로`, 'good'); }
