    if (this.trait('Once Upon A Time')) { this.prim.ouat += wounds; this.say(`Once Upon A Time 토큰 +${wounds} → ${this.prim.ouat}/4`); }
    if (this.trait('Eye for an Eye')) { this.prim.eyeTokens += wounds; this.say(`Eye for an Eye 토큰 +${wounds} → ${this.prim.eyeTokens}/${this.prim.eyeNeed}`); }
    if (A.t.sisyphean) { A.t.sisyphean = false; this.say(`${A.t.name}: Wound — Sisyphean Condition 제거`, 'good'); }
    this.c4OnWound(A.t); if (this.prim.def.djinnD) this.wishAdd(wounds, 'Wound'); if (this.prim.def.babelD) await this.babelOnWound(A);
    if (this.prim.def.midasD) { this.painAdd(wounds, 'Wound'); if (A.t.impaled) { this.say(`${A.t.name}: Impaled 상태로 Wound — VP 생성 (Impaled 유지)`, 'good'); this.createVP(null); } }
    this.prim.lastToWound = A.t; const total = this.woundCount();
    if (this.prim.traits['Snail of Nothing']) { this.prim.snail = (this.prim.snail || 0) + wounds; this.say(`Snail of Nothing: +AT 토큰 ${wounds} (총 ${this.prim.snail})`); }
    if (A.t.despair > 0) { A.t.despair--; this.say(`${A.t.name}: 상처를 입혀 Despair 1개 제거 (남은 ${A.t.despair})`, 'good'); }
    this.say(`WOUND! (+${wounds}) 누적 ${total}/${this.prim.wounds}`, 'good');
