    const want = tier === 3 ? null : tier; let rem = want ? this.ai.removeFirst(a => a.tier === want) : null;
    if (!rem && want) rem = this.ai.removeFirst(a => a.tier === want + 1);
    if (!rem) rem = this.lowest(this.ai, 'tier');
